using namespace std;
int main() {
  vector<int> a = {2, 5, 8, 12, 16, 23, 38};
  int target = 16, lo = 0, hi = a.size() - 1, found = -1;
  while (lo <= hi) {
    int mid = (lo + hi) / 2;
    cout << a[mid] << " ";
    if (a[mid] == target) { found = mid; break; }
    if (a[mid] < target) lo = mid + 1; else hi = mid - 1;
  }
  cout << "index " << found << endl;
  return 0;
}
